int main() {
    string mstr,nstr;
    int money;
    getline(cin, mstr);
    getline(cin, nstr);
    cin >> money;
    vector<int> mAns = split(mstr, ",");
    vector<int> nAns = split(nstr, ",");
​
    int n = mAns.size();
    vector<Node> ans;
    for (int i = 0; i < n; i++) {
        int cost = mAns[i];
        int sell = nAns[i];
        int profit = sell -cost;
        // 只考虑盈利的水果
        if (profit > 0) {
            ans.push_back({cost, sell, profit});
        }
    }
    // 按照成本从小到大排序
    sort(ans.begin(), ans.end(), cmp);
    // 设置为可供选择苹果的数量
    n = ans.size();
    priority_queue<Node, vector<Node>, compare> pq;
    int index = 0;
    int current = money;
    while (true) {
        // 当前money可以进的水果
        while (index < n && ans[index].cost <= current) {
            pq.push(ans[index]);
            index++;
        }
        // 没有可购买的水果了
        if (pq.empty()) {
            break;
        }
        // 当前可以购买的最大盈利的水果
        Node tmp = pq.top();
        pq.pop();
        // 盈利的钱
        current += tmp.profit;
    } 
​
    cout << current;
    return 0;
}

