import java.util.*;
​
class Node {
    int cost, sell, profit;

    Node(int cost, int sell, int profit) {
        this.cost = cost;
        this.sell = sell;
        this.profit = profit;
    }
}
​
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        // 读取输入
        String[] mStr = scanner.nextLine().split(",");
        String[] nStr = scanner.nextLine().split(",");
        int money = scanner.nextInt();

        int n = mStr.length;
        List<Node> fruits = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            int cost = Integer.parseInt(mStr[i]);
            int sell = Integer.parseInt(nStr[i]);
            int profit = sell - cost;
            if (profit > 0) { // 只考虑盈利的水果
                fruits.add(new Node(cost, sell, profit));
            }
        }

        // 按成本排序
        fruits.sort(Comparator.comparingInt(a -> a.cost));
​
        // 使用优先队列（大顶堆），按照利润排序
        PriorityQueue<Node> pq = new PriorityQueue<>((a, b) -> b.profit - a.profit);
​
        int index = 0;
        int current = money;
​
        while (true) {
            // 选择当前资金可以买入的水果
            while (index < fruits.size() && fruits.get(index).cost <= current) {
                pq.offer(fruits.get(index));
                index++;
            }
​
            if (pq.isEmpty()) {
                break;
            }
​
            // 购买利润最高的水果
            Node bestChoice = pq.poll();
            current += bestChoice.profit;
        }
​
        System.out.println(current);
    }
}
