package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
    "container/heap"
    "sort"
)
​
// Node 结构体
type Node struct {
    cost, sell, profit int
}
​
// 定义优先队列
type PriorityQueue []Node
​
func (pq PriorityQueue) Len() int            { return len(pq) }
func (pq PriorityQueue) Less(i, j int) bool  { return pq[i].profit > pq[j].profit } // 大顶堆
func (pq PriorityQueue) Swap(i, j int)       { pq[i], pq[j] = pq[j], pq[i] }
func (pq *PriorityQueue) Push(x interface{}) { *pq = append(*pq, x.(Node)) }
func (pq *PriorityQueue) Pop() interface{} {
    old := *pq
    n := len(old)
    x := old[n-1]
    *pq = old[0 : n-1]
    return x
}
​
// 字符串切割转换为整数数组
func splitToInts(s string, delimiter string) []int {
    parts := strings.Split(s, delimiter)
    result := make([]int, len(parts))
    for i, p := range parts {
        result[i], _ = strconv.Atoi(p)
    }
    return result
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
​
    // 读取输入
    scanner.Scan()
    mValues := splitToInts(scanner.Text(), ",")
    scanner.Scan()
    nValues := splitToInts(scanner.Text(), ",")
    scanner.Scan()
    money, _ := strconv.Atoi(scanner.Text())
​
    // 构造有效的水果集合
    var fruits []Node
    for i := 0; i < len(mValues); i++ {
        cost := mValues[i]
        sell := nValues[i]
        profit := sell - cost
        if profit > 0 {
            fruits = append(fruits, Node{cost, sell, profit})
        }
    }
​
    // 按照成本排序
    sort.Slice(fruits, func(i, j int) bool {
        return fruits[i].cost < fruits[j].cost
    })
​
    // 使用优先队列（最大堆）
    pq := &PriorityQueue{}
    heap.Init(pq)
​
    index := 0
    current := money
​
    for {
        // 添加可以购买的水果
        for index < len(fruits) && fruits[index].cost <= current {
            heap.Push(pq, fruits[index])
            index++
        }
​
        if pq.Len() == 0 {
            break
        }
​
        // 购买利润最高的水果
        bestChoice := heap.Pop(pq).(Node)
        current += bestChoice.profit
    }
​
    fmt.Println(current)
}
